// One versioned patch authority; descriptors are generated by the Rust crate.
// Preparation is outside process(). Trusted-host ABI pointers never leave here.
import {compilePitched,validatePitchedConfig} from './pitchedCompiler.js';
import {validatePercussionConfig} from './percussionConfig.js';
import {validatePianoConfig,PIANO_TYPES} from './pianoConfig.js';
import {validateIowaConfig,iowaFields} from './iowaConfig.js';
import {validateOwnedInsertsSpec} from './ownedInserts.js';
import {validateOwnedEffectsSpec} from './ownedEffects.js';
import {validateMixerConfig} from './mixerConfig.js';
import {validateClassicConfig,classicParameter} from './classicConfig.js';
import {validatePluckedConfig}from './pluckedConfig.js';
import {STRING_BODIES}from './ownedPluckedString.js';
import {validateOwnedMotionSpec}from './ownedMotion.js';
import {validateOwnedTapeSpec}from './ownedTape.js';
import {validateOwnedNativeCompressorSpec}from './ownedNativeCompressor.js';
import {validateOwnedNativeCompressorAutomationSpec}from './ownedNativeCompressorAutomation.js';
import {validateOwnedRackFxSpec}from './ownedRackFx.js';
